package com.tripcraft.service;

import com.opencsv.CSVReader; import org.apache.poi.ss.usermodel.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.util.*;
@Service public class BulkUploadService { private final JdbcTemplate db; public BulkUploadService(JdbcTemplate db){this.db=db;}
  public Map<String,Object> rooms(long hotelId,MultipartFile file){List<String> errors=new ArrayList<>();int imported=0,row=1;try{for(List<String> cells: rows(file)){row++;if(cells.size()<4){errors.add("Row "+row+": expected roomType,capacity,pricePerNight,totalUnits");continue;}try{int cap=Integer.parseInt(cells.get(1));int units=Integer.parseInt(cells.get(3));if(cap<1||units<0)throw new IllegalArgumentException("capacity or units invalid");db.update("INSERT INTO rooms(hotel_id,room_type,capacity,price_per_night,total_units,amenities) VALUES(?,?,?,?,?,?)",hotelId,cells.get(0),cap,Double.parseDouble(cells.get(2)),units,amenities(cells.size()>4?cells.get(4):""));imported++;}catch(Exception e){errors.add("Row "+row+": "+e.getMessage());}}}catch(Exception e){errors.add("File: "+e.getMessage());}return Map.of("imported",imported,"errors",errors);}
  public Map<String,Object> vehicles(long destinationId,MultipartFile file){List<String> errors=new ArrayList<>();int imported=0,row=1;try{for(List<String> c:rows(file)){row++;if(c.size()<9){errors.add("Row "+row+": expected type,model,seats,ac,pricePerDay,pricePerKm,driverIncluded,units,pickupCity");continue;}try{int seats=Integer.parseInt(c.get(2)),units=Integer.parseInt(c.get(7));db.update("INSERT INTO vehicles(vehicle_type,model,seat_capacity,air_conditioned,price_per_day,price_per_km,driver_included,units_available,pickup_city) VALUES(?,?,?,?,?,?,?,?,?)",c.get(0),c.get(1),seats,Boolean.parseBoolean(c.get(3)),Double.parseDouble(c.get(4)),Double.parseDouble(c.get(5)),Boolean.parseBoolean(c.get(6)),units,c.get(8));int vehicle=db.queryForObject("SELECT LAST_INSERT_ID()",Integer.class);db.update("INSERT INTO destination_vehicles(destination_id,vehicle_id) VALUES(?,?)",destinationId,vehicle);imported++;}catch(Exception e){errors.add("Row "+row+": "+e.getMessage());}}}catch(Exception e){errors.add("File: "+e.getMessage());}return Map.of("imported",imported,"errors",errors);}
  private List<List<String>> rows(MultipartFile file)throws Exception{if(file.getOriginalFilename()!=null&&file.getOriginalFilename().toLowerCase().endsWith(".xlsx")){List<List<String>> out=new ArrayList<>();try(Workbook w=WorkbookFactory.create(file.getInputStream())){for(Row r:w.getSheetAt(0)){if(r.getRowNum()==0)continue;List<String> cells=new ArrayList<>();for(Cell c:r){c.setCellType(CellType.STRING);cells.add(c.getStringCellValue().trim());}out.add(cells);}}return out;}try(CSVReader reader=new CSVReader(new InputStreamReader(file.getInputStream()))){List<List<String>> out=new ArrayList<>();String[] line;reader.readNext();while((line=reader.readNext())!=null)out.add(Arrays.asList(line));return out;}}
  private String amenities(String raw){if(raw==null||raw.isBlank())return "[]";if(raw.trim().startsWith("["))return raw;return "[\""+String.join("\",\"",raw.split("\\|"))+"\"]";}
}
